import tomllib
from pathlib import Path

def load_settings(env, path, overrides):
    options = {"poll_seconds": 11}
    options.update(tomllib.loads(Path(path).read_text())["monitor"])
    if "KILN_POLL_SECONDS" in env:
        options["poll_seconds"] = int(env["KILN_POLL_SECONDS"])
    options.update(overrides)
    return options
